#!/usr/bin/env node
/**
 * aekim — the AEK icon-manager CLI (IV round, A2 local-only).
 *
 * The agent-facing half of the icon manager: a human picks icons in the
 * webui's 图标管理 panel (click-to-copy / bulk-copy), and this CLI lets an
 * AGENT do the same thing from the terminal — list the whole registry,
 * show usage facts, or print the agent-handoff block straight to stdout
 * (pipe it into `pbcopy` / `clip` if you want the real clipboard).
 *
 * Data source: `data/icons.json` (the framework registry), generated by
 * `node scripts/aek/gen-icon-manifest.mjs --write` from the host's
 * `apps/aek-web/src/Icons.tsx`; and `data/icon-sets/*.json` (the curated
 * open-source sets, V6 round), vendored by
 * `node scripts/aek/gen-icon-sets.mjs --download` from GitHub repositories
 * via the `gh` CLI. Plain Node ESM, zero deps.
 *
 * @module @cheezmil/aek-icon-manager/bin/aekim
 */
import { existsSync, readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const manifestPath = path.join(here, '..', 'data', 'icons.json')
const setManifestPath = path.join(here, '..', 'data', 'icon-sets', 'manifest.json')

const USAGE = `aekim — list / inspect / copy the AEK frontend icon registry + open-source sets

Usage:
  aekim list [--json]          every framework icon name (one per line; --json = the manifest)
  aekim show <name...>         usage facts (framework icons)
  aekim show <set>:<name...>   usage facts (open-source set icons, e.g. lucide:search)
  aekim copy <name|set:name...>   the agent-handoff block (framework + set icons mixable)
  aekim copy --all             the block for EVERY framework icon
  aekim sets                  the open-source set catalog (counts, licenses, npm packages)
  aekim list --set <prefix>   every icon name of one open-source set

Pipe the output of copy/show to your platform's clipboard (pbcopy on macOS)
if you want the snippet on the real clipboard instead of on stdout.`

function fail(message, code = 1) {
  console.error(`aekim: ${message}`)
  process.exit(code)
}

function loadManifest() {
  try {
    const parsed = JSON.parse(readFileSync(manifestPath, 'utf8'))
    if (!Array.isArray(parsed.icons)) fail('manifest is corrupt (no icons array) — run: node scripts/aek/gen-icon-manifest.mjs --write')
    return parsed
  } catch (cause) {
    fail(`cannot read the icon manifest (${manifestPath}): ${cause?.message ?? cause}\nregenerate it with: node scripts/aek/gen-icon-manifest.mjs --write`)
  }
}

/** @returns the open-source set manifest, or undefined when the generator never ran. */
function loadSetManifest() {
  if (!existsSync(setManifestPath)) return undefined
  return JSON.parse(readFileSync(setManifestPath, 'utf8'))
}

/** @param set - one set meta row. @returns its per-set catalog. */
function loadSetData(set) {
  const file = path.join(here, '..', 'data', 'icon-sets', set.file)
  if (!existsSync(file)) fail(`set catalog ${set.file} is missing — regenerate with: node scripts/aek/gen-icon-sets.mjs --download`)
  return JSON.parse(readFileSync(file, 'utf8'))
}

/** @param name - a kebab icon name. @returns the guidance PascalCase name. */
function pascalOf(name) {
  return name.split(/[-_]+/).filter(part => part.length > 0).map(part => part.charAt(0).toUpperCase() + part.slice(1)).join('')
}

/** Fill a set's usage template for one icon. */
function setUsage(set, iconName) {
  return set.usage.replace(/\{pascal\}/gu, pascalOf(iconName)).replace(/\{name\}/gu, iconName)
}

const [command, ...rest] = process.argv.slice(2)
switch (command) {
  case 'list': {
    const json = rest.includes('--json')
    const setFlagIndex = rest.indexOf('--set')
    if (setFlagIndex !== -1) {
      const prefix = rest[setFlagIndex + 1]
      if (prefix === undefined) fail('--set needs a prefix (see: aekim sets)')
      const setManifest = loadSetManifest() ?? fail('no open-source set data — run: node scripts/aek/gen-icon-sets.mjs --download')
      const set = setManifest.sets.find(item => item.prefix === prefix) ?? fail(`unknown set "${prefix}" (available: ${setManifest.sets.map(item => item.prefix).join(', ')})`)
      const data = loadSetData(set)
      for (const iconName of Object.keys(data.icons)) console.log(iconName)
      break
    }
    if (json) {
      const manifest = loadManifest()
      console.log(JSON.stringify(manifest, null, 2))
      break
    }
    const manifest = loadManifest()
    for (const icon of manifest.icons) console.log(icon.name)
    break
  }
  case 'sets': {
    const setManifest = loadSetManifest() ?? fail('no open-source set data — run: node scripts/aek/gen-icon-sets.mjs --download')
    for (const set of setManifest.sets) {
      console.log(`${set.prefix}\t${set.name}\t${String(set.iconCount)} icons\t${set.license}\tnpm ${set.npm}\t(${set.repo})`)
    }
    break
  }
  case 'show':
  case 'copy': {
    const manifest = loadManifest()
    const byName = new Map(manifest.icons.map(icon => [icon.name, icon]))
    const setManifest = loadSetManifest()
    const sets = new Map((setManifest?.sets ?? []).map(set => [set.prefix, set]))
    let names
    if (rest.includes('--all')) {
      names = manifest.icons.map(icon => icon.name)
    } else {
      names = rest.filter(arg => !arg.startsWith('-'))
      if (names.length === 0) {
        console.error(USAGE)
        fail(`no icon names given (framework: ${[...byName.keys()].join(', ')}${setManifest ? `\nopen-source sets: ${[...sets.keys()].join(', ')} (use <set>:<name>)` : ''})`, 2)
      }
    }
    // Resolve each argument: plain name = framework icon; <set>:<name> = set icon.
    const resolved = []
    for (const name of names) {
      const colon = name.indexOf(':')
      if (colon > 0) {
        const scope = name.slice(0, colon)
        const iconName = name.slice(colon + 1)
        const set = sets.get(scope)
        if (set === undefined) fail(`unknown set "${scope}" (available: ${[...sets.keys()].join(', ') || 'none — run the generator'})`)
        const data = loadSetData(set)
        if (data.icons[iconName] === undefined) fail(`unknown icon "${iconName}" in set ${scope} (${String(Object.keys(data.icons).length)} icons; try: aekim list --set ${scope})`)
        resolved.push({ scope, iconName, set, usage: setUsage(set, iconName) })
        continue
      }
      const icon = byName.get(name)
      if (icon === undefined) fail(`unknown framework icon "${name}" (available: ${[...byName.keys()].join(', ')})`)
      resolved.push({ scope: 'fw', iconName: name, usage: icon.usage })
    }
    if (command === 'copy') {
      // The same block the webui panel puts on the clipboard, so the two
      // faces never drift.
      const lines = [
        manifest.usageHeader ?? 'AEK frontend icons (registry apps/aek-web/src/Icons.tsx, Lucide stroke style, 24×24 viewBox):',
        ...resolved.map(item => item.scope === 'fw'
          ? `- ${item.iconName} → ${item.usage}`
          : `// ${item.set.name} (${item.set.npm}, ${item.set.repo}, ${item.set.license})\n- ${item.scope}:${item.iconName} → ${item.usage}`),
      ]
      console.log(lines.join('\n'))
      break
    }
    // show: the facts an agent needs to place an icon in markup.
    for (const item of resolved) {
      if (item.scope === 'fw') {
        const icon = byName.get(item.iconName)
        console.log(`* ${icon.name}`)
        console.log(`  usage: ${icon.usage}`)
        console.log(`  style: ${manifest.style}`)
        console.log(`  source: ${manifest.source}`)
      } else {
        console.log(`* ${item.scope}:${item.iconName}`)
        console.log(`  usage: ${item.usage}`)
        console.log(`  license: ${item.set.license} (${item.set.repo})`)
        console.log(`  import package: ${item.set.npm}`)
      }
    }
    break
  }
  case undefined:
    console.log(USAGE)
    break
  default:
    console.error(USAGE)
    fail(`unknown command "${command}"`, 2)
}
